def transform(grid):
    # The uniform row separates two panels; compare corresponding cells.
    sep = next(r for r, row in enumerate(grid) if len(set(row)) == 1)
    top, bottom = grid[:sep], grid[sep + 1:]

    def common(panel):
        counts = {}
        for row in panel:
            for x in row:
                counts[x] = counts.get(x, 0) + 1
        return max(counts, key=counts.get)

    top_bg = common(top)
    bottom_bg = common(bottom)
    return [[3 if top[r][c] != top_bg and bottom[r][c] == bottom_bg
             else bottom_bg for c in range(len(top[0]))]
            for r in range(len(top))]
