def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a uniform separator row or column.
    divider = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            divider = ("row", r)
            break
    if divider is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                divider = ("col", c)
                break

    if divider[0] == "row":
        i = divider[1]
        first, second = grid[:i], grid[i + 1:]
    else:
        i = divider[1]
        first = [row[:i] for row in grid]
        second = [row[i + 1:] for row in grid]

    def background(panel):
        counts = {}
        for row in panel:
            for x in row:
                counts[x] = counts.get(x, 0) + 1
        return max(counts, key=counts.get)

    bg1, bg2 = background(first), background(second)
    return [[3 if first[r][c] != bg1 and second[r][c] == bg2 else bg2
             for c in range(len(first[0]))]
            for r in range(len(first))]
